begin;

update public.spell_catalog set name_ru='Создание магена', effect_summary='За 1 час превращаешь подготовленную человекоподобную куклу в магена выбранного типа. Созданный маген безоговорочно выполняет твои команды. Когда он появляется, твой максимум хитов уменьшается на величину его показателя опасности, минимум на 1; вернуть этот потерянный максимум может только заклинание «Исполнение желаний».', author_description='Постоянный искусственный слуга за очень реальную цену: дорогие материалы, час работы и кусок собственного максимума здоровья.', author_comment='Маген бесплатным не бывает. Просто часть счёта приходит не в золотых, а в максимальных хитах.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Расходуются ртуть стоимостью 500 зм и человекоподобная кукла. Сложный кристаллический жезл стоимостью не менее 1500 зм требуется, но не расходуется. Точный набор смешанных компонентов хранится текстом, поскольку расходуются не все части требования.', material='флакон ртути стоимостью 500 зм и человекоподобная кукла — расходуются; сложный кристаллический жезл стоимостью не менее 1500 зм — не расходуется', material_cost_gp=500, material_consumed=true, material_consumption='mixed' where slug='create-magen' and source_kind='official';

update public.spell_catalog set name_ru='Корона звёзд', effect_summary='На 1 час вокруг головы появляются семь звёздных искр. Бонусным действием можешь отправить одну в существо или предмет в пределах 120 футов и совершить дальнобойную атаку заклинанием; при попадании цель получает 4к12 урона излучением. Искра расходуется независимо от попадания.', author_description='Семь мощных дальнобойных выстрелов, которые заранее загружаются одним действием и затем расходуются бонусными действиями без концентрации.', author_comment='Корона для мага, который считает драгоценности боеприпасами.', upcast='За каждый уровень ячейки выше 7 создаётся ещё 2 звёздные искры.', notes='При 4+ оставшихся искрах корона даёт яркий свет на 30 футов и тусклый ещё на 30; при 1–3 искрах — тусклый свет на 30 футов. Заклинание заканчивается после расходования последней искры.' where slug='crown-of-stars' and source_kind='official';

update public.spell_catalog set name_ru='Драконье преображение', effect_summary='Бонусным действием на срок до 1 минуты с концентрацией получаешь драконьи свойства: слепое зрение 30 футов, скорость полёта 60 футов и дыхание силовой энергией. При сотворении и бонусным действием в последующие ходы можешь выдохнуть 60-футовый конус: цели делают спасбросок Ловкости, получая 6к8 урона силовым полем при провале или половину при успехе.', author_description='Полёт, особое зрение и повторяемое дыхание в одной форме — почти полноценный временный драконий режим.', author_comment='Крылья ненастоящие, а шесть к8 изо рта почему-то вполне настоящие.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Статуэтка дракона стоимостью не менее 500 зм используется как фокус и не расходуется.', material='статуэтка дракона стоимостью не менее 500 зм — не расходуется', material_cost_gp=500, material_consumed=false, material_consumption='none' where slug='draconic-transformation' and source_kind='official';

update public.spell_catalog set name_ru='Сон о Синей Завесе', effect_summary='Ты и до восьми добровольных существ в пределах 20 футов засыпаете на 6 часов и видите другой мир Материального плана. Если эффект продолжается полные 6 часов, группа переносится в безопасное место этого мира, связанное с используемым магическим предметом или происхождением одного из участников.', author_description='Очень медленная, но межмировая телепортация. Она требует не координаты, а физическую связь с миром назначения.', author_comment='Шесть часов сна — довольно дешёвый билет, учитывая, что пункт назначения может быть другим миром.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Нужен магический предмет из мира назначения либо добровольное существо, родившееся там. Урон прерывает эффект на затронутом существе; если урон получаешь ты, перенос срывается для всей группы.', material='магический предмет из мира назначения либо добровольное существо, родившееся в этом мире — не расходуется', material_cost_gp=null, material_consumed=false, material_consumption='none' where slug='dream-of-the-blue-veil' and source_kind='official';

update public.spell_catalog set name_ru='Слово силы: Боль', effect_summary='Произносишь слово, поражающее одно видимое существо в пределах 60 футов. Если у цели 100 хитов или меньше и она не иммунна к Очарованию, её охватывает мучительная боль: скорость не может превышать 10 футов, атаки, проверки характеристик и все спасброски кроме Телосложения совершаются с помехой. Перед попыткой сотворить заклинание цель должна пройти спасбросок Телосложения; при провале заклинание теряется.', author_description='Не наносит прямой урон, но превращает опасную цель с уже просевшим здоровьем в почти неработоспособную.', author_comment='Слово силы здесь не убивает. Оно заставляет цель всерьёз задуматься, не было ли это гуманнее.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Цель делает спасбросок Телосложения в конце каждого своего хода и при успехе прекращает боль. Если при сотворении у неё больше 100 хитов, заклинание не действует.' where slug='power-word-pain' and source_kind='official';

update public.spell_catalog set name_ru='Синостодвимер Симбул', effect_summary='Касаешься существа и на 1 час даёшь ему способ превращать собственные Кости Хитов в лечение при сотворении магии. Когда цель тратит ячейку на заклинание, она может сразу потратить число неиспользованных Костей Хитов, равное уровню этой ячейки, бросить их и восстановить хиты в размере суммы бросков плюс твой модификатор заклинательной характеристики.', author_description='Заклинание превращает запас Костей Хитов в аварийное лечение, которое срабатывает прямо вместе с расходованием ячеек.', author_comment='Симбул нашла ещё один ресурс на листе персонажа и немедленно превратила его в магическую экономику.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Кости Хитов действительно расходуются. Для активации цель должна потратить ячейку заклинания и иметь достаточно неиспользованных Костей Хитов.' where slug='simbul-s-synostodweomer' and source_kind='official';

update public.spell_catalog set name_ru='Храм богов', effect_summary='За 1 час создаёшь магический храм размером до 120-футового куба, существующий 24 часа. Ты определяешь внешний вид и тех, кто может управлять дверью. Выбранные типы существ — небожители, элементали, феи, исчадия и/или нежить — должны пройти спасбросок Харизмы, чтобы войти, а внутри испытывают магические помехи. Храм также защищает от прорицания и вмешательства с Эфирного плана и усиливает лечение заклинаниями.', author_description='Полноценная временная святыня и укрепление: безопасное помещение, фильтр для нежелательных существ и дополнительные защитные свойства.', author_comment='У жреца теперь есть способ поставить храм там, где пять минут назад был просто пустырь.', upcast='Не усиливается ячейкой более высокого уровня. Если создавать храм в одном месте каждый день в течение года, он становится постоянным.', notes='Священный символ стоимостью не менее 5 зм не расходуется. Точный внешний вид храма выбирает заклинатель.', casting_time='1 час', material='священный символ стоимостью не менее 5 зм — не расходуется', material_cost_gp=5, material_consumed=false, material_consumption='none' where slug='temple-of-the-gods' and source_kind='official';

update public.spell_catalog set name_ru='Связь сущностей', effect_summary='Два видимых существа в пределах 60 футов делают спасброски Телосложения; если они находятся не далее 30 футов друг от друга, спасаются с помехой, а добровольная цель может провалить автоматически. Если оба проваливают, они связываются на срок до 1 часа с концентрацией: любой урон, полученный одним, получает и второй; любое восстановление хитов одного в том же количестве получает и другой.', author_description='Делает двух существ общей системой здоровья. Можно связать союзников ради удвоения лечения или противников ради крайне неприятного отражения урона.', author_comment='Разделённая боль, разделённое лечение и абсолютно общий повод нервничать.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Если хотя бы одна цель успешно спасается, заклинание не срабатывает. Связь действует независимо от дальнейшего расстояния и заканчивается для обоих, если один опускается до 0 хитов. Платиновый шнур стоимостью 250 зм расходуется.', material='катушка платинового шнура стоимостью не менее 250 зм — расходуется', material_cost_gp=250, material_consumed=true, material_consumption='always' where slug='tether-essence' and source_kind='official';

update public.spell_catalog set name_ru='Вихрь', effect_summary='Создаёшь в точке в пределах 300 футов вихрь радиусом 10 футов и высотой 30 футов на срок до 1 минуты с концентрацией. Существо, в которое вихрь входит или которое впервые за ход входит в него, делает спасбросок Ловкости: при провале получает 10к6 дробящего урона, при успехе — половину. Большая или меньшая цель при провале дополнительно делает спасбросок Силы или становится Опутанной вихрем.', author_description='Большая управляемая зона контроля: она ездит по полю, подбирает существ, поднимает их вверх и может выбросить после освобождения.', author_comment='Торнадо обычно не слушает команды. Поэтому это заклинание седьмого уровня.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Действием вихрь можно переместить до 30 футов. Опутанная цель поднимается внутри него и перемещается вместе с ним; действием может сделать проверку Силы или Ловкости против Сл заклинаний и при успехе освобождается, после чего её отбрасывает. Материальный компонент — кусочек соломы.', material='кусочек соломы — не расходуется', material_cost_gp=null, material_consumed=false, material_consumption='none' where slug='whirlwind' and source_kind='official';

commit;
